"""Grouped, sourced facts for Cybercab and the Semi versions.

Every figure comes from the 19 November 2026 research sheets. Status is one of
official, reported, video, derived, estimated, unclear, conflict, unknown.
Estimated rows are arithmetic checks, not Tesla specifications.
"""


def R(en_l, en_v, nl_l, nl_v, status):
    return {"en": (en_l, en_v), "nl": (nl_l, nl_v), "status": status}


def S(en, nl, rows, notes_en=None, notes_nl=None):
    block = {"title": {"en": en, "nl": nl}, "rows": rows}
    if notes_en:
        block["notes"] = {"en": notes_en, "nl": notes_nl}
    return block


